head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03
scwin.gNdvNotiNo;
scwin.gNotiProcsStatCd;
scwin.gDate;
scwin.vScrenID = 'ULDSTF00001.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    // 현재날짜 셋팅	
    scwin.gDate = $c.ut.cGetToday("yyyymmdd");
    edt_SrchDay.setValue(scwin.gDate);
};


// 조회조건 유효성 검증
scwin.fn_CheckCond = function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_SrchDay).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_SrchDay.focus();
        return;
    }
    var vStatCnt = 0;
    if (chb_stat_00.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_10.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_30.checked == true) {
        vStatCnt++;
    }
    // 처리상태 1개 이상 체크
    if (vStatCnt < 1) {
        $c.win.alert("처리상태를 한개 이상  선택하시오.");
        chb_stat_00.focus();
        return;
    }
    scwin.gDate = $c.stf.getObjectValue(edt_SrchDay);
    scwin.fn_Search();
};
scwin.getChkValue = function(obj) {
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};



// 목록조회
scwin.fn_Search = function() {
    var url = "/NightNoti.do?method=listNotiSrchAll" + "&SRCH_DATE=" + scwin.gDate + "&STAT_00=" + scwin.getChkValue(chb_stat_00) + "&STAT_10=" + scwin.getChkValue(chb_stat_10) + "&STAT_30=" + scwin.getChkValue(chb_stat_30) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_NdvNotiList.DataID = encodeURI(url);
    dts_NdvNotiList.reset();
    $c.cm.ShowWin(grd_Grid);
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gNdvNotiNo = dts_NdvNotiList.getCellData(eval(obj), "NDV_NOTI_NO");
    scwin.gNotiProcsStatCd = dts_NdvNotiList.getCellData(eval(obj), "NOTI_PROCS_STAT_CD");
};
scwin.fn_checkAll = function() {
    // 전체가 체크일때 
    if (chb_stat_all.checked == true) {
        chb_stat_00.setValue(1);
        chb_stat_10.setValue(1);
        chb_stat_30.setValue(1);
    } else {
        chb_stat_00.setValue(0);
        chb_stat_10.setValue(0);
        chb_stat_30.setValue(0);
    }
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    var url = "/dsclnightnoti/ULDSTF00002.gfm?NDV_NOTI_NO=" + scwin.gNdvNotiNo + "&NOTI_PROCS_STAT_CD=" + scwin.gNotiProcsStatCd;
    var winTitle = "";
    if (scwin.gNotiProcsStatCd == "00") {
        // 처리중
        url = url + "&POP_GB=P";
        winTitle = "야간시장 공지 검토";
    } else if (scwin.gNotiProcsStatCd == "10") {
        // 검토
        // 팀장 또는 당번인 경우(책임자)
        //alert("gJobTitle : "+gJobTitle + " gDutyYn : "+gDutyYn + " gDutyChrg : "+gDutyChrg);
        if (scwin.gJobTitle == "09" || scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y') {
            url = url + "&POP_GB=P";
            winTitle = "야간시장 공지 승인";
        } else {
            url = url + "&POP_GB=R";
            winTitle = "야간시장 공지 상세보기";
        }
    } else if (scwin.gNotiProcsStatCd == "30") {
        // 승인
        url = url + "&POP_GB=R";
        winTitle = "야간시장 공지 상세보기";
    }
    if (colid == "NDV_NOTI_TITLE") {
        await $c.frame.CreateDialogFrame("gform", url, winTitle, 200, 100, 870, 500, "window");
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_CheckCond();
};
scwin.dts_NdvNotiList_OnLoadError = function() {
    $c.stf.alert_error(dts_NdvNotiList);
    $c.cm.CloseWin(0, grd_Grid);
};
scwin.dts_NdvNotiList_OnLoadCompleted = function(rowcount) {
    if (dts_NdvNotiList.errorMsg) {
        $c.win.alert(dts_NdvNotiList.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.btn_New_fix_onclick = async function() {
    await $c.frame.CreateDialogFrame("gform", "/dsclnightnoti/ULDSTF00002.gfm?POP_GB=N", "야간시장 공지 입력", 200, 100, 870, 500, "window");
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "야간거래공지 목록", "", "8");
};
scwin.img_Cal_onclick = function() {
    popUpCalendar2(edt_SrchDay);
};
scwin.gform_onload = function() {
    scwin.fn_SetCode();
    scwin.fn_Search();

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
};
scwin.chb_stat_all_onclick = function() {
    scwin.fn_checkAll();
};
